// AWI sementara: buang baris konversi LABEL_DISINI dari WPCode (tag AW-17836993296 tetap). Hapus setelah dipakai.
add_action('init', function () {
	if (!isset($_GET['awi_wpc']) || $_GET['awi_wpc'] !== 'k93hf2xq') return;
	global $wpdb;
	$re = '#gtag\(\s*\x27event\x27\s*,\s*\x27conversion\x27\s*,\s*\{\s*\x27send_to\x27\s*:\s*\x27AW-17836993296/LABEL_DISINI\x27\s*\}\s*\);#';
	$rep = '/* konversi WA lewat event GA4 klik_whatsapp (snippet 32) */';
	$out = array();
	$p = get_post(10762);
	if ($p) {
		$new = preg_replace($re, $rep, $p->post_content, -1, $n);
		if ($n) { $wpdb->update($wpdb->posts, array('post_content' => $new, 'post_status' => 'publish'), array('ID' => 10762)); clean_post_cache(10762); }
		$out['post_replaced'] = $n;
	}
	$opt = get_option('wpcode_snippets');
	$cnt = 0;
	$walk = function ($v) use (&$walk, $re, $rep, &$cnt) {
		if (is_array($v)) { foreach ($v as $k => $x) $v[$k] = $walk($x); return $v; }
		if (is_string($v) && strpos($v, 'LABEL_DISINI') !== false) { $v = preg_replace($re, $rep, $v, -1, $c); $cnt += $c; }
		return $v;
	};
	if ($opt) { $opt = $walk($opt); update_option('wpcode_snippets', $opt); }
	$out['cache_replaced'] = $cnt;
	if (function_exists('wpcode') && isset(wpcode()->cache) && method_exists(wpcode()->cache, 'cache_all_loaded_snippets')) { wpcode()->cache->cache_all_loaded_snippets(); $out['rebuilt'] = true; }
	$left = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->options} WHERE option_value LIKE '%LABEL_DISINI%'") + $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_content LIKE '%LABEL_DISINI%'");
	$out['sisa_label'] = (int) $left;
	do_action('litespeed_purge_all');
	wp_send_json($out);
}, 1);
